INSERT INTO `marketing_templates` VALUES (1,'New Member Welcome','welcome','🎉 Welcome to THE CLUB 777®, {name}! Your Member Code is {member_code}. Behind Shehnai Garden, Near Railway Station, Jhajjar (Phone: {gym_phone}). We are thrilled to guide your fitness transformation!','active','2026-08-12 21:21:02'),(2,'Birthday Special Wishes','birthday','🎂 Happy Birthday {name}! THE CLUB 777® wishes you great health, strength, and happiness! 🎉 Enjoy a 15% discount on your next membership renewal or cafe voucher today!','active','2026-08-12 21:21:02'),(3,'Joining Anniversary Special','anniversary','⭐ Happy Workout Anniversary {name}! Thank you for completing another strong year with THE CLUB 777®. Enjoy a free PT & Spa consultation session!','active','2026-08-12 21:21:02'),(4,'Membership Expiry Alert','expiry_reminder','⚠️ Hi {name}, your FITZONE membership plan is expiring on {end_date}. Renew today to continue your streak without interruption!','active','2026-08-12 21:21:02'),(9,'3 Weeks Expiry Reminder','expiry_3_weeks','👋 Hi {name}, this is a gentle reminder that your {plan_name} at THE CLUB 777® is expiring in 3 weeks on {end_date}. Renew early to stay committed to your fitness journey! Contact: {gym_phone}','active','2026-08-20 09:05:18'),(10,'1 Week Expiry Reminder','expiry_1_week','⚠️ Hi {name}, your {plan_name} at THE CLUB 777® will expire in 7 days on {end_date}. Don\'t pause your workout streak—visit the front desk or renew your membership today! Contact: {gym_phone}','active','2026-08-20 09:05:18'),(11,'2 Days Expiry Reminder','expiry_2_days','🚨 Urgent Alert: Hi {name}, only 2 days remain on your THE CLUB 777® membership ({end_date}). Renew today to keep your biometric gate access active without interruption! Contact: {gym_phone}','active','2026-08-20 09:05:18'),(12,'Same Day Expiry Alert','expiry_same_day','🔔 Membership Expiring Today: Hi {name}, your THE CLUB 777® membership expires today ({end_date}). Please renew today to continue enjoying uninterrupted gym & pool access! Contact: {gym_phone}','active','2026-08-20 09:05:18'),(13,'Fees Due & Expired Membership Alert','fees_due','🚨 Fees Due Notice: Hi {name}, your {plan_name} at THE CLUB 777® has expired on {end_date}. Your gym access & biometric punch are currently paused. Please clear your renewal dues or visit the reception at Jhajjar today! Phone: {gym_phone}','active','2026-08-20 09:18:27'),(110,'Same-Day Trial Welcome & 48h Offer','','🔥 *Welcome to FITZONE Gym, {name}!* 🔥\n\nWe are thrilled you experienced your trial pass with us today! 💪\n\n🎁 *Special Same-Day Conversion Offer:* Upgrade to our Monthly or Yearly Plan within 48 hours and receive:\n✅ ₹1,000 Admission Fee 100% WAIVED\n✅ 1 Free Personal Training Session\n✅ Customized Nutrition Diet Chart\n\nVisit reception or call us at {gym_phone} to claim!','active','2026-08-20 09:46:01'),(111,'Diwali Mega Dhamaka Offer','','🪔 *Happy Diwali from FITZONE Gym, {name}!* 🪔\n\nLight up your fitness journey with our *DIWALI MEGA DHAMAKA OFFER*:\n💥 Get *3 MONTHS EXTRA FREE* on any 6 or 12 Month Membership!\n💥 Free Access to Swimming Pool & Steam Bath\n💥 Free Fitness Assessment & Body Scan\n\nOffer valid for limited slots! Call {gym_phone} now.','active','2026-08-20 09:46:01'),(112,'Festive Season Special Offer','','🎉 *Festive Season Special Discount at FITZONE Gym!* 🎉\n\nDear {name}, enjoy *FLAT 25% OFF* on all Annual Memberships & Personal Training Packages this festive week!\n\n💪 Don\'t miss out—start your transformation today. Contact reception at {gym_phone}.','active','2026-08-20 09:46:01'),(113,'New Year Fitness Resolution Offer','','🚀 *New Year, Stronger You!* 🚀\n\nDear {name}, kickstart your New Year resolution with FITZONE Gym:\n🔥 Join our 12-Month Plan and get 2 Months FREE + ₹500 Supplement Voucher!\n\nVisit {gym_name} or call {gym_phone} to get started.','active','2026-08-20 09:46:01'),(114,'Trial Pass Welcome & Experience Message','','🏋️‍♂️ Namaste {name}! Welcome to FITZONE Gym! 🎉 We are thrilled you took your trial workout session with us today!\n\n🔥 Hope you had a power-packed workout session! Our certified trainers, state-of-the-art equipment, and shower/steam facilities are here for your fitness transformation.\n\n🎁 SPECIAL TRIAL CONVERSION PERK:\nUpgrade to our Regular 3-Month, 6-Month or Annual Plan within 48 hours & get:\n✅ 100% Admission Fee Waived\n✅ FREE 1-on-1 Personal Training Session\n✅ FREE Customized Nutrition Chart\n\nVisit front desk or call {gym_phone} to claim your offer! 💪','active','2026-08-20 09:46:11'),(115,'Diwali Mega Dhamaka Offer','','🪔 Happy Diwali {name}! May this festival of lights bring abundant health, strength, and joy to you and your family! ✨\n\n💥 DIWALI MEGA FITNESS DHAMAKA:\nGet UP TO 40% OFF on 6-Month & Annual Gym + Pool Memberships!\n🎁 Buy 1-Year Membership & Get 2 Months EXTRA FREE + Free Gym Kit Bag!\n\n⏳ Offer valid till Diwali weekend only. Visit FITZONE Gym or call {gym_phone} to lock your festive pass! 🏋️‍♂️🔥','active','2026-08-20 09:46:11'),(116,'Festive Season Special Offer','','🎊 Festive Greetings from FITZONE Gym, {name}! Celebrate this festive season by gifting yourself supreme health & fitness! ✨\n\n🎁 FESTIVE SPECIAL DEAL:\nEnjoy FLAT 25% DISCOUNT on all Transformation & Annual Passes + Free Diet Plan!\n\nContact reception or call {gym_phone} to claim today! 🚀','active','2026-08-20 09:46:11'),(117,'New Year Fitness Resolution Offer','','🎉 Happy New Year, {name}! 🚀 Make 2027 your fittest and strongest year yet at FITZONE Gym!\n\n💥 NEW YEAR SPECIAL PASS:\nGet FLAT 30% OFF on all 6-Month & 12-Month memberships + 2 Free PT Sessions!\n\nReply RESOLUTION to lock your festive discount! 💪','active','2026-08-20 09:46:11'),(118,'Same-Day Trial Welcome & 48h Offer','','🔥 *Welcome to FITZONE Gym, {name}!* 🔥\n\nWe are thrilled you experienced your trial pass with us today! 💪\n\n🎁 *Special Same-Day Conversion Offer:* Upgrade to our Monthly or Yearly Plan within 48 hours and receive:\n✅ ₹1,000 Admission Fee 100% WAIVED\n✅ 1 Free Perso